import unittest
from solution import is_valid_brackets

class TestBracketValidator(unittest.TestCase):
    def test_simple_balanced(self):
        self.assertTrue(is_valid_brackets("{[()]}"))
        self.assertFalse(is_valid_brackets("{[(])}"))

    def test_brackets_inside_strings(self):
        self.assertTrue(is_valid_brackets("foo('{')"))
        self.assertTrue(is_valid_brackets('let a = ["(", "]"];'))
        self.assertFalse(is_valid_brackets('foo("(")'))

    def test_escaped_quotes_inside_strings(self):
        self.assertTrue(is_valid_brackets('("hello \"world\" [test]")'))

if __name__ == '__main__':
    unittest.main()
